(function(){ window.PPPE_QUESTOES = window.PPPE_QUESTOES || {}; Object.assign(window.PPPE_QUESTOES, {
"Regime jurídico-administrativo e princípios da administração": [
{ text: "A respeito do conceito e das fontes do direito administrativo, assinale a alternativa correta.", options: ["O direito administrativo disciplina apenas a atividade do Poder Executivo, pois Legislativo e Judiciário não exercem função administrativa.", "A jurisprudência e o costume administrativo podem autorizar a Administração a agir contrariamente à lei, desde que haja reiteração.", "A Constituição e as leis são fontes primárias; regulamentos, jurisprudência, doutrina e costumes auxiliam a interpretação e a aplicação.", "A doutrina é fonte primária e prevalece sobre a lei quando esta for omissa quanto à conveniência do ato."], correct: 2, exp: "Constituição e leis são as fontes primárias, e as demais fontes apenas auxiliam. A alternativa sobre jurisprudência e costume contra a lei é errada, pois eles não autorizam agir contra a lei." },
{ text: "O diretor de uma unidade prisional estabelece, dentro da lei e de sua competência, a escala de serviço dos policiais penais. Essa atuação caracteriza", options: ["função administrativa, ainda que exercida em órgão do Poder Executivo.", "função legislativa atípica, pois cria regras gerais de conduta.", "função jurisdicional, pois resolve conflitos entre servidores.", "atividade política de governo, alheia ao regime jurídico-administrativo."], correct: 0, exp: "Organizar o serviço interno é função administrativa. Não se trata de função política nem legislativa, pois apenas executa e organiza dentro da lei." },
{ text: "Sobre a supremacia do interesse público e a indisponibilidade, julgue as afirmativas e assinale a correta.", options: ["A supremacia autoriza a Administração a suprimir direitos fundamentais sempre que invocar conveniência estatal.", "A indisponibilidade impede qualquer acordo, mesmo que autorizado em lei.", "O agente público é dono do interesse público e pode renunciá-lo livremente, se motivar a decisão.", "A supremacia não significa prevalência automática de qualquer conveniência estatal, pois proporcionalidade e devido processo continuam obrigatórios."], correct: 3, exp: "A supremacia opera nos limites constitucionais e legais, com proporcionalidade. A indisponibilidade não impede acordos autorizados em lei, o que torna errada a alternativa que afirma o contrário." },
{ text: "Assinale a alternativa que apresenta apenas princípios expressamente previstos no caput do art. 37 da Constituição Federal para a Administração Pública.", options: ["Legalidade, razoabilidade, proporcionalidade, publicidade e eficiência.", "Legalidade, impessoalidade, moralidade, publicidade e eficiência.", "Legalidade, finalidade, motivação, moralidade e continuidade.", "Impessoalidade, autotutela, publicidade, eficiência e segurança jurídica."], correct: 1, exp: "O rol expresso é o LIMPE. Razoabilidade, proporcionalidade, finalidade, motivação, autotutela e continuidade são princípios implícitos." },
{ text: "Uma unidade prisional divulga relatório de vistoria contendo critérios e resultados, mas oculta dados pessoais e informações legalmente sigilosas. Quanto ao princípio da publicidade, essa conduta é", options: ["regular, pois a publicidade é regra de transparência e admite ressalvas de sigilo constitucional e legal.", "irregular, pois a publicidade exige a divulgação integral de qualquer informação administrativa.", "irregular, pois a eficiência afasta qualquer hipótese de sigilo.", "regular apenas se houver autorização do servidor mais antigo da unidade."], correct: 0, exp: "A publicidade é regra, mas não licença para divulgar dados protegidos. A tese de divulgação integral ignora as hipóteses legítimas de sigilo." },
{ text: "Um gestor nomeia para função de confiança, sem critério técnico algum, apenas um amigo pessoal, que atua de modo regular. O princípio mais diretamente violado é o da", options: ["continuidade do serviço público.", "publicidade.", "impessoalidade, que veda favorecimentos e orienta a atuação à finalidade pública.", "segurança jurídica."], correct: 2, exp: "Favorecer pessoa por amizade viola a impessoalidade. A circunstância de o nomeado atuar de modo regular não elimina o favorecimento." },
{ text: "Quanto à autotutela, assinale a incorreta.", options: ["Permite à Administração controlar os próprios atos.", "Autoriza anular atos ilegais.", "Autoriza revogar atos por inconveniência ou inoportunidade.", "Autoriza a Administração a ignorar a segurança jurídica e a proteção da confiança ao desfazer atos."], correct: 3, exp: "A autotutela convive com segurança jurídica e proteção da confiança, que protegem estabilidade legítima. As demais alternativas descrevem corretamente seu alcance." },
{ text: "A respeito do princípio da eficiência, é correto afirmar que", options: ["pode ser invocado para convalidar qualquer ilegalidade, desde que o resultado seja econômico.", "demanda boa prestação do serviço e uso responsável dos recursos, sem afastar os demais princípios.", "substitui a legalidade quando o gestor entender que o resultado será melhor.", "aplica-se apenas à Administração indireta."], correct: 1, exp: "Eficiência exige bom resultado e uso responsável de recursos, mas não corrige ilegalidade. O art. 37 alcança direta e indireta de todos os Poderes." },
{ text: "Diante de risco concreto à segurança prisional, a autoridade determina providência legal de contenção e registra a razão da medida, respeitando os limites dos direitos assegurados. Essa conduta ilustra a observância de", options: ["indisponibilidade absoluta, que proíbe medidas restritivas.", "motivação, proporcionalidade e supremacia do interesse público nos limites legais.", "autotutela, pois a Administração revoga ato anterior.", "arbitrariedade tolerada pela supremacia do interesse público."], correct: 1, exp: "Registrar a razão (motivação) e conter dentro dos limites legais (proporcionalidade) é a atuação correta. A supremacia não é poder ilimitado." },
{ text: "No que tange à legalidade administrativa, é correto afirmar que", options: ["a Administração exige autorização do ordenamento para agir, devendo identificar competência e fundamento jurídico, sobretudo ao restringir direitos ou aplicar sanção.", "a Administração pode fazer tudo que a lei não proíbe, como o particular.", "a legalidade dispensa indicação de competência quando a medida for urgente.", "a legalidade restringe-se ao Poder Executivo."], correct: 0, exp: "Legalidade administrativa exige atuação autorizada pelo ordenamento, diferente da autonomia do particular. O art. 37 alcança todos os Poderes." },
],
"Organização administrativa: administração direta, indireta e entidades paralelas": [
{ text: "Em sentido objetivo, material ou funcional, a expressão Administração Pública designa", options: ["os órgãos e entidades que exercem a função administrativa.", "a atividade administrativa, como serviço público, polícia administrativa, fomento e intervenção.", "somente as pessoas políticas e seus órgãos.", "exclusivamente os órgãos governamentais que definem diretrizes políticas."], correct: 1, exp: "O sentido objetivo trata do que a Administração faz. O sentido subjetivo responde quem administra, e Administração direta refere-se às pessoas políticas." },
{ text: "A criação, dentro de uma secretaria estadual, de setores de segurança e de saúde, ligados por hierarquia, constitui exemplo de", options: ["descentralização por outorga.", "descentralização por delegação.", "desconcentração, pois distribui competências dentro da mesma pessoa jurídica.", "criação de entidade paraestatal."], correct: 2, exp: "Distribuir competências internamente na mesma pessoa jurídica é desconcentração. Descentralização envolve pessoa jurídica diversa." },
{ text: "Sobre órgãos públicos, assinale a alternativa correta.", options: ["Em regra, possuem personalidade jurídica própria.", "São centros de competências integrados à estrutura de uma pessoa jurídica e, em regra, não têm personalidade própria.", "São sempre pessoas jurídicas de direito privado.", "Equivalem às entidades da Administração indireta."], correct: 1, exp: "Órgão é centro de competências sem personalidade própria, salvo capacidade processual excepcional para defender prerrogativas. Entidade indireta tem personalidade própria e não é órgão." },
{ text: "A Administração direta é composta por", options: ["União, estados, Distrito Federal e municípios, atuando por seus órgãos.", "autarquias, fundações, empresas públicas e sociedades de economia mista.", "organizações sociais e serviços sociais autônomos.", "apenas a União e suas autarquias."], correct: 0, exp: "A direta reúne as pessoas políticas. As entidades citadas na segunda alternativa formam a indireta, e as demais são entidades paralelas." },
{ text: "Quanto à instituição das entidades da Administração indireta, é correto afirmar que", options: ["a autarquia é criada diretamente por lei específica, ao passo que empresa pública, sociedade de economia mista e fundação dependem de autorização legislativa.", "todas são criadas diretamente por decreto do chefe do Executivo.", "empresas públicas são criadas diretamente por lei, e autarquias dependem de autorização.", "dependem sempre de emenda constitucional."], correct: 0, exp: "Autarquia é criada por lei específica; as demais exigem autorização legislativa, observadas as exigências constitucionais." },
{ text: "Assinale a alternativa incorreta sobre a Administração indireta.", options: ["Autarquias e fundações públicas de direito público exercem atividades típicas sob regime predominantemente público.", "Empresas estatais têm personalidade de direito privado e regime híbrido.", "Uma empresa pública pode explorar atividade econômica ou prestar serviço público, conforme sua finalidade legal.", "A supervisão ministerial ou equivalente cria hierarquia entre a entidade e a Administração direta."], correct: 3, exp: "Supervisão finalística não equivale a hierarquia, pois são pessoas jurídicas distintas. As demais alternativas descrevem corretamente a indireta." },
{ text: "A concessão de serviço de transporte coletivo a uma empresa privada, mediante delegação, é exemplo de", options: ["desconcentração.", "avocação.", "descentralização por delegação a particular, sem hierarquia entre as pessoas, mas com controle e fiscalização previstos.", "criação de órgão público."], correct: 2, exp: "Concessão e permissão são formas de delegação a particular. Não há hierarquia entre pessoas distintas, embora possa haver fiscalização." },
{ text: "As entidades paralelas ou paraestatais", options: ["integram a Administração direta, pois recebem recursos públicos.", "integram a Administração indireta, pois colaboram com o Estado.", "não integram a Administração direta nem a indireta, podendo cooperar com o Estado e receber recursos, sujeitas a transparência e prestação de contas.", "tornam-se órgãos públicos ao firmarem parceria com o Estado."], correct: 2, exp: "A parceria não transforma automaticamente a entidade privada em órgão público nem afasta o dever de prestar contas." },
{ text: "Em relação aos sentidos de Administração Pública, julgue: A Secretaria de Administração é estrutura subjetiva; organizar concurso ou gerir contratos é atividade objetiva.", options: ["Incorreta, pois ambos são sentido objetivo.", "Incorreta, pois a secretaria é sentido objetivo e o concurso é subjetivo.", "Correta, pois o sentido subjetivo identifica quem administra e o objetivo identifica o que a Administração faz.", "Incorreta, pois não há distinção doutrinária entre os sentidos."], correct: 2, exp: "Subjetivo responde quem administra; objetivo responde o que se faz. A prova costuma indicar expressamente o critério adotado." },
{ text: "Uma autarquia estadual ligada a uma secretaria de Estado, quanto à relação com ela, apresenta", options: ["subordinação hierárquica plena, como qualquer setor interno.", "ausência total de controle.", "personalidade própria, sujeita a supervisão ou controle finalístico, sem hierarquia.", "natureza de entidade paralela do terceiro setor."], correct: 2, exp: "A autarquia tem personalidade distinta; a supervisão não se confunde com hierarquia. Não é entidade paralela, pois integra a indireta." }
],
"Atos administrativos: conceito, requisitos, atributos e classificação": [
{ text: "A ordem formal que determina uma inspeção em cela e a inspeção material realizada pelos policiais penais classificam-se, respectivamente, como", options: ["fato administrativo e ato administrativo.", "ato administrativo e fato administrativo.", "ato administrativo e ato normativo.", "fato administrativo e fato jurídico natural."], correct: 1, exp: "A ordem é manifestação de vontade com efeitos jurídicos (ato); a execução material é fato administrativo. Não se confunde o ato com sua execução." },
{ text: "São requisitos ou elementos tradicionais do ato administrativo:", options: ["competência, finalidade, forma, motivo e objeto.", "legalidade, moralidade, publicidade, motivo e eficiência.", "competência, mérito, forma, publicidade e prazo.", "finalidade, oportunidade, conveniência, objeto e forma."], correct: 0, exp: "A doutrina tradicional aponta competência, finalidade, forma, motivo e objeto. Mérito, conveniência e oportunidade referem-se à discricionariedade." },
{ text: "Quanto aos conceitos, é correto afirmar que, no ato administrativo,", options: ["o motivo é o efeito jurídico imediato do ato.", "o objeto é o pressuposto fático e jurídico que enseja a decisão.", "a finalidade é o modo de exteriorização do ato.", "o motivo compreende os pressupostos de fato e de direito, e o objeto é o efeito jurídico imediato."], correct: 3, exp: "Motivo é pressuposto fático e jurídico; objeto é o efeito imediato; forma é o modo de exteriorização; finalidade é o resultado público legal." },
{ text: "Sobre os atributos dos atos administrativos, assinale a alternativa correta.", options: ["A presunção de legitimidade é absoluta e não admite prova em contrário.", "A autoexecutoriedade é atributo universal, presente em todos os atos.", "A presunção é relativa; a autoexecutoriedade autoriza execução direta em hipóteses legais ou de urgência, não sendo atributo universal.", "A imperatividade impede o controle judicial."], correct: 2, exp: "A presunção admite prova em contrário e a autoexecutoriedade depende de previsão legal ou urgência. O controle judicial continua possível." },
{ text: "Um ato administrativo pode ser válido e, ainda assim, não produzir efeitos imediatos. Isso é possível porque", options: ["validade e eficácia são sinônimos.", "validade é conformidade com o ordenamento, e a eficácia pode depender de publicação, condição ou termo.", "todo ato válido é automaticamente eficaz.", "a eficácia depende exclusivamente do mérito."], correct: 1, exp: "Validade e eficácia são distintas. Um ato conforme à lei pode aguardar publicação, condição ou termo para produzir efeitos." },
{ text: "Um ato cuja formação depende da conjugação de vontades de órgãos distintos para constituir um único ato é classificado como", options: ["simples.", "composto.", "complexo.", "bilateral."], correct: 2, exp: "No ato complexo, vontades de órgãos distintos integram-se em um ato único. No composto há ato principal e manifestação acessória que o aprova; no simples, há a manifestação de um órgão." },
{ text: "No ato composto, segundo a classificação usual,", options: ["há ato principal e manifestação acessória que o aprove ou confira eficácia.", "há duas vontades de igual valor que formam um único ato.", "há apenas uma vontade de um órgão.", "os destinatários são indeterminados."], correct: 0, exp: "O composto depende de ato principal e manifestação acessória. Duas vontades que se fundem caracterizam o complexo." },
{ text: "A respeito do silêncio administrativo, é correto afirmar que", options: ["sempre significa deferimento do pedido.", "sempre significa indeferimento do pedido.", "a consequência depende da lei aplicável e, sem previsão, a omissão pode configurar descumprimento do dever de decidir, sujeito a controle.", "não pode ser objeto de controle."], correct: 2, exp: "Não há regra geral de deferimento ou indeferimento. Sem previsão legal, a omissão pode configurar descumprimento do dever de decidir." },
{ text: "Sobre mérito administrativo e discricionariedade, assinale a incorreta.", options: ["O mérito é o espaço juridicamente permitido de conveniência e oportunidade.", "Está presente nos atos discricionários.", "Não abrange escolha contrária à lei, à finalidade ou aos princípios.", "No ato vinculado, a autoridade escolhe livremente a conveniência e a oportunidade."], correct: 3, exp: "No ato vinculado a lei define pressupostos e consequência, sem margem de conveniência e oportunidade. As demais alternativas estão corretas." },
{ text: "Os atos gerais e individuais distinguem-se porque", options: ["os gerais se dirigem a destinatários indeterminados e os individuais identificam destinatários.", "os gerais têm destinatário certo e os individuais são abstratos.", "os gerais são sempre vinculados e os individuais, discricionários.", "os individuais dependem de duas vontades."], correct: 0, exp: "O critério é a determinação dos destinatários. Vinculação ou discricionariedade é outra classificação, independente dessa." }
],
"Atos administrativos: espécies, vícios, extinção e convalidação": [
{ text: "Na classificação por espécie, os atos que detalham a aplicação da lei sem inovar além da competência são os", options: ["negociais.", "enunciativos.", "punitivos.", "normativos."], correct: 3, exp: "Normativos detalham a aplicação da lei; negociais consentem; enunciativos certificam ou opinam; punitivos aplicam sanções após processo devido." },
{ text: "Segundo a teoria dos motivos determinantes, se a Administração declara os motivos de fato e de direito de um ato,", options: ["a validade do ato fica vinculada à existência e à veracidade desses motivos.", "a discricionariedade protege o ato mesmo que os motivos sejam falsos.", "os motivos são irrelevantes se o ato for discricionário.", "a motivação só vincula se for obrigatória por lei."], correct: 0, exp: "Motivo falso ou inexistente compromete o ato, ainda que a motivação não fosse originalmente obrigatória. A discricionariedade não protege justificativa inventada." },
{ text: "Um servidor é transferido sob a justificativa de necessidade de serviço que, comprovadamente, não existia. Nesse caso,", options: ["o ato é válido por ser discricionário.", "o ato é válido, pois o Judiciário não pode examinar motivos.", "a falsidade do motivo declarado compromete a validade do ato.", "o ato só pode ser revogado."], correct: 2, exp: "Pela teoria dos motivos determinantes, a inexistência do motivo declarado afeta a validade. Discricionariedade não autoriza justificativa inexistente." },
{ text: "Sobre vícios dos atos administrativos, assinale a alternativa correta.", options: ["Todo vício é insanável e impõe a anulação.", "Erro formal corrigível pode admitir saneamento, mas desvio de finalidade normalmente compromete o ato de modo insanável.", "O desvio de finalidade torna-se legítimo com mera correção documental.", "Vícios de competência nunca podem ser analisados quanto à delegabilidade."], correct: 1, exp: "É preciso analisar a natureza do vício e a possibilidade de saneamento. Desvio de finalidade não se corrige com ajuste documental." },
{ text: "Quanto às categorias doutrinárias de invalidade, o ato inexistente é aquele", options: ["que possui vício sanável de forma.", "em que falta elemento mínimo para reconhecer manifestação estatal como ato jurídico.", "revogado por inconveniência.", "praticado com excesso de poder, mas válido."], correct: 1, exp: "Inexistente é a categoria em que falta o mínimo para haver manifestação estatal. Ato anulável apresenta vício sanável, conforme o regime." },
{ text: "A anulação do ato administrativo", options: ["retira ato válido por conveniência e oportunidade.", "retira ato ilegal, pela Administração em autotutela ou pelo Judiciário quando provocado, respeitados devido processo e segurança jurídica.", "decorre do descumprimento de condição pelo beneficiário.", "corrige defeito sanável preservando o ato."], correct: 1, exp: "Anulação tem como causa a ilegalidade. Retirada de ato válido por conveniência é revogação, e descumprimento de condição gera cassação." },
{ text: "Assinale a alternativa que apresenta corretamente a revogação.", options: ["Extingue ato ilegal com efeitos retroativos em regra.", "Extingue ato válido por conveniência ou oportunidade, em regra com efeitos prospectivos, e não cabe sobre ato vinculado ou já exaurido.", "Cabe sobre qualquer ato vinculado.", "É exclusiva do Poder Judiciário."], correct: 1, exp: "Revogação atinge ato válido por mérito, prospectivamente, e não alcança atos vinculados ou exauridos. Ela não é competência exclusiva do Judiciário." },
{ text: "Um policial penal obteve autorização condicionada ao cumprimento de determinado requisito, que deixou de observar, e a Administração desfaz o ato por esse motivo. Trata-se de", options: ["cassação, por descumprimento de condição necessária à manutenção do ato.", "revogação, por mudança de oportunidade.", "convalidação.", "anulação por vício de competência."], correct: 0, exp: "Cassação decorre do descumprimento, pelo beneficiário, de condição necessária à manutenção do ato. Revogação envolve juízo de conveniência da Administração." },
{ text: "A convalidação, nos termos expostos, é cabível quando", options: ["o defeito é sanável e não há lesão ao interesse público nem prejuízo a terceiros.", "o ato apresenta objeto ilegal.", "há desvio de finalidade.", "a Administração decide extinguir ato inconveniente."], correct: 0, exp: "Convalidação corrige defeito sanável sem lesão ao interesse público nem a terceiros. Objeto ilegal e finalidade desviada normalmente comprometem o ato." },
{ text: "A apuração disciplinar que reúne comunicações, instrução, defesa e decisão exemplifica", options: ["ato complexo único.", "procedimento administrativo, sequência ordenada de atos preparatórios e decisórios, com garantias conforme a lei.", "ato enunciativo.", "ato normativo geral."], correct: 1, exp: "Procedimento é a sequência ordenada de atos com participação do interessado quando necessário. Cada etapa prepara a decisão final e deve observar a norma." }
],
"Poderes e deveres da administração; uso e abuso do poder": [
{ text: "Sobre o poder hierárquico, assinale a alternativa correta.", options: ["Existe hierarquia entre pessoas jurídicas distintas da Administração.", "Permite organizar a estrutura, expedir ordens legais, fiscalizar, delegar e avocar nos limites normativos.", "Autoriza o cumprimento de ordem manifestamente ilegal, pois a obediência hierárquica elimina o dever de legalidade.", "Aplica-se a particulares em geral."], correct: 1, exp: "A hierarquia organiza a estrutura interna e opera nos limites normativos. Não existe entre pessoas jurídicas distintas nem sobre particulares, e não legitima ordem manifestamente ilegal." },
{ text: "O poder disciplinar", options: ["autoriza a Administração a punir qualquer cidadão sem base legal.", "apura infrações e aplica sanções a servidores e a particulares sujeitos a vínculo especial, com contraditório e ampla defesa.", "dispensa a competência da autoridade, desde que haja urgência.", "limita-se à esfera penal."], correct: 1, exp: "O poder disciplinar alcança quem tem vínculo especial com a Administração e exige competência, contraditório e ampla defesa. Não permite sancionar qualquer cidadão." },
{ text: "A chefia de uma unidade prisional pode organizar turnos e fiscalizar registros. A aplicação de sanção disciplinar a um servidor, por sua vez, exige", options: ["apenas a convicção da chefia.", "apuração conforme o regime funcional e oportunidade de defesa.", "a prévia condenação criminal.", "decisão do Poder Legislativo."], correct: 1, exp: "A sanção exige apuração e defesa. Não se pressupõe culpa pelo cargo, e a esfera administrativa não depende de condenação criminal." },
{ text: "Sobre o poder regulamentar, assinale a alternativa incorreta.", options: ["Consiste em editar atos normativos secundários que viabilizam a fiel execução da lei.", "Regulamentos não podem contrariar a lei nem criar obrigações ou sanções sem fundamento legal.", "A Constituição admite hipóteses delimitadas de decreto autônomo.", "Permite ao regulamento inovar livremente na ordem jurídica, criando infrações disciplinares independentemente de lei."], correct: 3, exp: "O regulamento é subordinado à lei e não pode criar infração sem base legal. O decreto autônomo é exceção constitucional de alcance restrito." },
{ text: "Segundo a Constituição, o decreto autônomo é admitido para", options: ["criar tributos e infrações penais.", "organização e funcionamento da Administração federal, sem aumento de despesa nem criação ou extinção de órgãos, e extinção de cargos ou funções vagos.", "criar órgãos públicos livremente.", "substituir a lei em qualquer matéria urgente."], correct: 1, exp: "As hipóteses são delimitadas. Isso não transforma decreto em lei geral." },
{ text: "Se um decreto regulamentar exorbita do poder de regulamentar, o Congresso Nacional", options: ["nada pode fazer.", "pode sustar o ato normativo, nos termos constitucionais.", "deve aguardar o trânsito em julgado de ação penal.", "pode apenas recomendar a revogação."], correct: 1, exp: "A Constituição permite ao Congresso sustar atos normativos do Executivo que exorbitem do poder regulamentar." },
{ text: "Sobre o poder de polícia, é correto afirmar que", options: ["condiciona ou restringe direitos e atividades em benefício de interesses coletivos, nos limites legais, com proporcionalidade e processo devido.", "elimina as liberdades públicas quando o interesse coletivo estiver em jogo.", "dispensa base legal, pois decorre da supremacia do interesse público.", "possui obrigatoriamente discricionariedade, coercibilidade e autoexecutoriedade em toda medida."], correct: 0, exp: "O poder de polícia limita direitos para proteger interesse coletivo, mas exige base legal e proporcionalidade. Seus atributos não aparecem invariavelmente em toda medida." },
{ text: "A revista e a fiscalização de acesso à unidade prisional devem", options: ["seguir protocolo legal e tratar as pessoas com dignidade, sem transformar o controle em punição arbitrária.", "ser feitas livremente conforme o humor do agente.", "ser evitadas, pois o poder de polícia não alcança unidades prisionais.", "ser punitivas para servir de exemplo."], correct: 0, exp: "Medidas de segurança devem se apoiar em regras e fatos verificáveis. Controle de acesso não é punição arbitrária." },
{ text: "Quanto à delegação de atividades de polícia, a jurisprudência exposta admite", options: ["que qualquer particular exerça integralmente o poder de polícia.", "que a delegação ocorra a todo particular, sem requisitos.", "delegações delimitadas a certas pessoas jurídicas de direito privado da Administração indireta que preencham requisitos.", "que nenhuma atividade de polícia seja delegada em hipótese alguma."], correct: 2, exp: "A delegação é delimitada e restrita a certas entidades privadas da Administração indireta. Não se pode afirmar que qualquer particular exerça integralmente o poder de polícia." },
{ text: "O abuso de poder em que o agente usa competência que possui para objetivo alheio ao previsto na norma denomina-se", options: ["excesso de poder.", "desvio de finalidade.", "omissão legítima.", "avocação."], correct: 1, exp: "Desvio de finalidade usa competência existente para fim alheio ao previsto. Excesso de poder ocorre quando o agente excede sua competência." }
],
"Intervenção do Estado na propriedade e bens públicos": [
{ text: "A modalidade de intervenção que permite o uso transitório de bem particular em hipóteses legais, sem transferência da propriedade, é a", options: ["desapropriação.", "ocupação temporária.", "tombamento.", "limitação administrativa de natureza geral."], correct: 1, exp: "A ocupação temporária permite uso transitório. A desapropriação transfere compulsoriamente a propriedade." },
{ text: "Diante de perigo público iminente, a Administração pode requisitar bem particular. Quanto à indenização, é correto afirmar que", options: ["será sempre prévia e em dinheiro, como na desapropriação.", "é indevida em qualquer hipótese.", "pode ser devida posteriormente, se houver dano, nos termos constitucionais.", "depende de lei estadual específica para cada caso."], correct: 2, exp: "Requisição atende necessidade pública urgente e pode gerar indenização ulterior se houver dano. Não se confunde com desapropriação." },
{ text: "Assinale a alternativa que associa corretamente a modalidade interventiva e sua característica.", options: ["Tombamento: transferência compulsória da propriedade.", "Limitação administrativa: obrigação geral de não fazer ou de suportar.", "Servidão administrativa: obrigação geral dirigida a toda a coletividade sem especificidade.", "Desapropriação: uso transitório sem indenização."], correct: 1, exp: "Limitações impõem obrigações gerais. Servidão estabelece ônus específico, tombamento protege patrimônio cultural, e desapropriação transfere a propriedade." },
{ text: "Segundo o Código Civil, os bens públicos classificam-se em", options: ["móveis, imóveis e semoventes.", "de uso comum do povo, de uso especial e dominicais.", "afetados, desafetados e privados.", "federais, estaduais e municipais exclusivamente."], correct: 1, exp: "A classificação do Código Civil é uso comum, uso especial e dominicais. As demais são classificações diversas." },
{ text: "O prédio destinado ao funcionamento de uma unidade prisional estadual é classificado como bem", options: ["de uso comum do povo.", "dominical.", "de uso especial.", "privado do Estado, sem proteção especial."], correct: 2, exp: "Prédios afetados a serviço público são de uso especial. Dominicais não têm afetação específica." },
{ text: "A respeito do regime dos bens públicos, assinale a incorreta.", options: ["Bens de uso comum e especial são inalienáveis enquanto conservarem essa qualificação.", "Em regra, são impenhoráveis.", "Não estão sujeitos a usucapião.", "O bem dominical equivale a bem privado comum, livremente alienável sem qualquer formalidade."], correct: 3, exp: "Bem dominical integra o patrimônio da pessoa pública e sua alienação exige requisitos legais. Não equivale a bem privado comum." },
{ text: "Para alienar equipamento público inservível, a autoridade deve", options: ["vender diretamente, pois a Administração é proprietária.", "documentar interesse público justificado, avaliação prévia e o procedimento legal adequado.", "dispensar a avaliação por conveniência.", "doar a quem solicitar primeiro."], correct: 1, exp: "A alienação exige justificativa, avaliação e observância da lei, incluindo a Lei nº 14.133/2021. Não se presume liberdade de venda." },
{ text: "A utilização privativa de bem público por particular dá-se mediante", options: ["título adequado, como autorização, permissão ou concessão de uso, conforme a lei e a natureza do bem.", "simples ocupação de fato, que gera propriedade por usucapião.", "apenas por meio de concessão de serviço público.", "ato verbal sem formalização."], correct: 0, exp: "O uso privativo exige título adequado. Usucapião não incide sobre bens públicos." },
{ text: "A autorização de uso de bem público é, geralmente,", options: ["estável e vinculada.", "precária e discricionária.", "sinônimo de concessão de serviço público.", "irrevogável."], correct: 1, exp: "A autorização é em geral precária e discricionária. Permissão e concessão têm regime e estabilidade distintos, e nenhuma se confunde com delegação de serviço." },
{ text: "No domínio econômico, segundo a Constituição, a exploração direta de atividade econômica pelo Estado é", options: ["a regra geral.", "excepcional e condicionada aos casos constitucionais, convivendo regulação e fiscalização com a livre iniciativa.", "proibida em qualquer circunstância.", "permitida sem qualquer condição por empresa pública."], correct: 1, exp: "A atuação direta é excepcional. A regulação e a fiscalização convivem com a livre iniciativa." }
],
"Licitações, contratos administrativos e contratação direta": [
{ text: "São modalidades de licitação previstas na Lei nº 14.133/2021:", options: ["pregão, concorrência, concurso, leilão e diálogo competitivo.", "convite, tomada de preços, concorrência, concurso e leilão.", "pregão, convite, concorrência, leilão e diálogo competitivo.", "tomada de preços, pregão, concorrência, concurso e leilão."], correct: 0, exp: "Convite e tomada de preços foram excluídos da lei geral. As cinco modalidades são pregão, concorrência, concurso, leilão e diálogo competitivo." },
{ text: "Quanto ao âmbito de aplicação da Lei nº 14.133/2021, em regra,", options: ["aplica-se às empresas públicas e sociedades de economia mista.", "aplica-se às Administrações diretas, autárquicas e fundacionais, e as empresas estatais são regidas pela Lei nº 13.303/2016.", "aplica-se apenas à União.", "aplica-se exclusivamente a obras."], correct: 1, exp: "Empresas públicas e sociedades de economia mista, em regra, sujeitam-se à Lei das Estatais. A lei geral alcança direta, autárquica e fundacional." },
{ text: "A escolha da modalidade de licitação, segundo a lei, relaciona-se", options: ["somente ao valor estimado da contratação.", "ao objeto e às condições legais, não ao valor por si só.", "à preferência do gestor.", "ao tamanho da unidade requisitante."], correct: 1, exp: "O critério não é o valor isolado. A compra de bens comuns pode ser estruturada como pregão, com especificação objetiva." },
{ text: "A fase preparatória da licitação inclui", options: ["apenas a publicação do edital.", "planejamento, definição da necessidade e do objeto, estimativa de custos e análise de riscos quando cabível.", "a homologação.", "o julgamento das propostas."], correct: 1, exp: "A fase preparatória antecede o edital e trata de planejamento, objeto, estimativa e riscos. Homologação e julgamento são fases posteriores." },
{ text: "Sobre o procedimento, assinale a alternativa correta.", options: ["A habilitação pode ser antecipada, mediante ato motivado e previsão editalícia.", "A inversão de fases é automática em qualquer licitação.", "O edital não vincula a Administração.", "A habilitação nunca precede o julgamento."], correct: 0, exp: "A inversão de fases depende de justificativa e previsão no edital. O edital vincula Administração e participantes." },
{ text: "Assinale o critério de julgamento que NÃO consta entre os citados para a Lei nº 14.133/2021.", options: ["Menor preço.", "Maior desconto.", "Maior retorno econômico.", "Menor tempo de existência da empresa."], correct: 3, exp: "Os critérios incluem menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance e maior retorno econômico." },
{ text: "No diálogo competitivo,", options: ["não há conversa com licitantes.", "a Administração dialoga com licitantes previamente selecionados para desenvolver solução antes das propostas finais.", "o objeto é sempre material de consumo comum.", "a modalidade só se aplica a leilão de bens."], correct: 1, exp: "O diálogo competitivo tem hipóteses e dinâmica próprias, com diálogo antes das propostas finais." },
{ text: "Acerca da execução do contrato administrativo, é correto afirmar que", options: ["a Administração não precisa fiscalizar a execução.", "alterações unilaterais são livres e ilimitadas.", "a Administração deve designar acompanhamento e fiscalizar, registrando ocorrências e exigindo a correção de falhas.", "o equilíbrio econômico-financeiro não é protegido."], correct: 2, exp: "Alterações unilaterais só ocorrem nas hipóteses e limites legais, preservado o equilíbrio. O fiscal registra atrasos e comunica a autoridade." },
{ text: "Sobre contratação direta, assinale a incorreta.", options: ["Na inexigibilidade, a competição é inviável nas hipóteses legais.", "Na dispensa, a competição pode ser viável, mas a lei autoriza não licitar.", "Ambas exigem instrução processual, justificativa do contratado e do preço e autorização competente.", "Contratação direta significa contratação sem processo e sem observância de princípios."], correct: 3, exp: "Contratação direta exige processo. A ausência de disputa não afasta princípios e transparência." },
{ text: "Fracionar uma despesa para fugir da licitação ou escapar do limite de dispensa por valor é", options: ["regular, desde que o valor de cada parte seja pequeno.", "irregular.", "obrigatório em compras recorrentes.", "permitido se houver urgência qualquer."], correct: 1, exp: "O fracionamento para fugir da licitação é irregular. Os limites de valor são atualizados, devendo-se conferir a versão vigente." }
],
"Convênios, consórcios, parcerias público-privadas e concessões": [
{ text: "Sobre o convênio administrativo, assinale a alternativa correta.", options: ["É a típica relação de interesses contrapostos própria do contrato.", "Dispensa prestação de contas dos recursos transferidos.", "É instrumento de cooperação para objetivos de interesse comum, com mútua colaboração e plano de trabalho.", "Só pode ser firmado entre particulares."], correct: 2, exp: "Convênio é cooperação por interesse comum, ao contrário do contrato. Recursos transferidos devem ser aplicados no objeto e prestar contas." },
{ text: "O consórcio público, regido pela Lei nº 11.107/2005, é", options: ["associação apenas entre empresas privadas.", "associação entre entes federativos para objetivos de interesse comum, podendo adquirir personalidade de direito público ou privado, conforme a lei.", "sempre órgão sem personalidade.", "formado sem protocolo de intenções."], correct: 1, exp: "O consórcio reúne entes federativos e pode ter personalidade de direito público (associação pública) ou privado. O protocolo de intenções e a ratificação legislativa estruturam sua formação." },
{ text: "Pernambuco e municípios decidem cooperar em serviço regional de interesse comum. A cooperação", options: ["deve ser formalizada por instrumento adequado, com objeto, obrigações e prestação de contas definidos, sem eliminar competências nem controles.", "elimina as competências constitucionais de cada ente.", "dispensa o controle sobre os recursos públicos.", "só é possível por concessão de serviço."], correct: 0, exp: "A cooperação não elimina competências constitucionais nem os controles sobre recursos públicos." },
{ text: "Na concessão de serviço público, nos termos da Lei nº 8.987/1995,", options: ["a delegação é feita sem licitação.", "o concessionário assume a titularidade do serviço.", "o prazo é indeterminado.", "a delegação ocorre mediante licitação e contrato, a pessoa jurídica ou consórcio de empresas, por sua conta e risco e por prazo determinado."], correct: 3, exp: "Delegar a execução não transfere a titularidade: o poder concedente continua titular, com deveres de regulação e fiscalização." },
{ text: "Assinale a alternativa que trata corretamente da permissão de serviço público.", options: ["É delegada sem licitação.", "É formalizada por contrato de adesão, precedida de licitação, com precariedade e revogabilidade nos termos da lei.", "Equivale a doação de bem público.", "É sinônimo universal de autorização."], correct: 1, exp: "Permissão também pressupõe licitação. A autorização tem natureza e regime diversos e não é sinônimo de concessão ou permissão." },
{ text: "A parceria público-privada (Lei nº 11.079/2004) é contrato administrativo de", options: ["concessão comum, apenas.", "convênio de cooperação.", "concessão patrocinada ou administrativa.", "permissão de uso de bem público."], correct: 2, exp: "PPP não se confunde com concessão comum. Divide-se em patrocinada e administrativa." },
{ text: "Na PPP patrocinada,", options: ["a tarifa cobrada dos usuários é complementada por contraprestação pecuniária do parceiro público.", "a Administração é usuária direta do serviço, sem tarifa.", "não há contraprestação do parceiro público.", "só há obra pública, sem serviço."], correct: 0, exp: "Na patrocinada soma-se tarifa e contraprestação pública. Na administrativa, a Administração é usuária direta ou indireta do serviço." },
{ text: "Segundo a Lei nº 11.079/2004, é vedada a PPP cujo", options: ["contrato preveja repartição de riscos.", "contrato exija garantias.", "objeto seja a prestação de serviços de forma continuada.", "objeto único seja o fornecimento de mão de obra, a instalação de equipamentos ou a execução de obra pública."], correct: 3, exp: "A lei exige repartição objetiva de riscos e estruturação adequada. Valores e requisitos podem mudar, devendo-se consultar o texto consolidado." },
{ text: "Sobre a extinção das delegações de serviço, a encampação é", options: ["retomada por interesse público durante o prazo, mediante lei autorizativa específica e prévia indenização.", "consequência do inadimplemento do concessionário.", "extinção pelo término do prazo.", "extinção por falência."], correct: 0, exp: "Encampação é retomada por interesse público; caducidade decorre de inadimplemento, após processo e garantias legais." },
{ text: "Assinale a alternativa que NÃO representa característica do serviço adequado segundo a Lei nº 8.987/1995.", options: ["Regularidade.", "Continuidade.", "Modicidade tarifária.", "Exclusividade do concessionário em qualquer circunstância."], correct: 3, exp: "O serviço adequado observa regularidade, continuidade, eficiência, segurança, atualidade, generalidade, cortesia e modicidade tarifária." }
],
"Controle da administração e processo administrativo (Lei nº 9.784/1999)": [
{ text: "O controle exercido pela própria Administração, por autotutela, recursos e supervisão, denomina-se controle", options: ["judicial.", "legislativo.", "administrativo.", "social externo."], correct: 2, exp: "O controle administrativo pode alcançar legalidade e, nos limites de competência, mérito. O judicial atua quando provocado." },
{ text: "A respeito do controle judicial da Administração, assinale a correta.", options: ["Aprecia a juridicidade quando provocado e pode invalidar ilegalidades, sem substituir escolhas discricionárias legítimas.", "O Judiciário substitui a Administração em qualquer escolha discricionária.", "É vedado em relação a atos administrativos.", "Só ocorre de ofício."], correct: 0, exp: "O controle judicial é de juridicidade. Mérito legítimo não é substituído pelo Judiciário." },
{ text: "Os tribunais de contas", options: ["integram o Poder Judiciário.", "julgam ações judiciais comuns.", "não podem auditar contratos.", "exercem controle externo com auxílio ao Legislativo, podendo determinar correções e aplicar sanções dentro de suas competências."], correct: 3, exp: "Tribunais de contas auxiliam o Legislativo e não integram o Judiciário." },
{ text: "No âmbito da Lei nº 9.784/1999, é correto afirmar que a lei", options: ["regula o processo administrativo no âmbito da Administração Pública federal e dos Poderes Legislativo e Judiciário federais quando exercem função administrativa.", "rege diretamente todos os processos administrativos estaduais de Pernambuco.", "revoga as normas especiais de processo disciplinar.", "aplica-se apenas ao Executivo municipal."], correct: 0, exp: "Seu âmbito é federal, com aplicação subsidiária em situações pertinentes. Deve-se conferir a lei estadual ou norma especial." },
{ text: "São princípios do processo administrativo previstos na Lei nº 9.784/1999, entre outros:", options: ["sigilo absoluto, oralidade exclusiva e livre convencimento.", "apenas legalidade e moralidade.", "supremacia do hierarca e irrecorribilidade.", "legalidade, finalidade, motivação, razoabilidade, proporcionalidade, ampla defesa, contraditório, segurança jurídica e eficiência."], correct: 3, exp: "A lei prevê um rol amplo de princípios, incluindo ampla defesa e contraditório." },
{ text: "Sobre a motivação das decisões, assinale a alternativa correta.", options: ["É dispensada nas decisões que imponham sanção.", "Nunca pode se valer de parecer.", "Deve ser explícita, clara e congruente, podendo adotar fundamentos de parecer ou informação incorporados ao ato.", "É facultativa em decisão de recurso."], correct: 2, exp: "A autoridade deve motivar decisões que neguem, limitem ou afetem direitos, imponham sanções ou decidam recursos. A remissão é possível se os fundamentos forem incorporados." },
{ text: "Quanto ao recurso administrativo, é correto afirmar que", options: ["tem sempre efeito suspensivo automático.", "pode ser interposto por razões de legalidade e de mérito, e a sua existência não suspende automaticamente os efeitos, salvo previsão ou decisão em contrário.", "só cabe por razões de mérito.", "não existe no processo administrativo federal."], correct: 1, exp: "Recurso não tem sempre efeito suspensivo. Prazos e instâncias devem ser verificados no texto aplicável." },
{ text: "Em processo administrativo disciplinar, é correto afirmar que a autoridade competente", options: ["está sempre vinculada ao relatório da comissão, sem poder divergir.", "pode punir sem defesa se houver urgência.", "não precisa motivar a decisão.", "decide conforme o regime jurídico aplicável e pode divergir motivadamente do relatório nos limites legais."], correct: 3, exp: "A comissão instrui e relata; a autoridade decide. Exigem-se apuração imparcial, defesa e decisão motivada." },
{ text: "Antes de decidir sanção disciplinar, a autoridade deve", options: ["apreciar as provas de defesa e explicar por que as considera suficientes ou insuficientes.", "ignorar as provas de defesa.", "dispensar a comunicação dos fatos ao acusado.", "aguardar o fim de qualquer ação penal."], correct: 0, exp: "A decisão motivada pressupõe apreciação da defesa. A independência entre esferas é regra, com repercussões específicas previstas em lei." },
{ text: "A sindicância, no contexto disciplinar,", options: ["jamais pode ter função investigativa.", "sempre dispensa o contraditório.", "pode ter função investigativa ou, quando a lei permitir, resultar em sanção, não dispensando garantias quando houver efeito punitivo.", "equivale ao julgamento definitivo do Judiciário."], correct: 2, exp: "Havendo efeito punitivo, as garantias de defesa são necessárias." }
],
"Agentes públicos e responsabilidade civil, penal e administrativa": [
{ text: "A expressão agente público", options: ["designa somente servidores titulares de cargo efetivo.", "exclui os agentes políticos.", "não abrange particulares em colaboração.", "é ampla e abrange quem exerce função estatal, ainda que transitoriamente ou sem remuneração."], correct: 3, exp: "Agente público é gênero e inclui agentes políticos, estatutários, empregados públicos e particulares em colaboração. Cargo, emprego e função não são sinônimos." },
{ text: "O ocupante de cargo regido por estatuto denomina-se servidor", options: ["celetista.", "estatutário.", "temporário de empresa privada.", "particular em colaboração."], correct: 1, exp: "Estatutário ocupa cargo; empregado público ocupa emprego regido pela legislação trabalhista." },
{ text: "O contratado temporário exerce função", options: ["permanente em cargo efetivo.", "sem qualquer base legal.", "exclusivamente de livre nomeação.", "para necessidade temporária de excepcional interesse público, nos termos constitucionais e legais."], correct: 3, exp: "A contratação temporária exige excepcional interesse público temporário. Não se trata de titular de cargo efetivo." },
{ text: "Quanto ao ingresso, a Constituição exige concurso para investidura em cargo ou emprego público, ressalvadas", options: ["as nomeações para cargos em comissão declarados em lei de livre nomeação e exoneração e outras exceções constitucionais.", "todas as funções administrativas.", "qualquer indicação política.", "apenas os cargos de nível superior."], correct: 0, exp: "Cargo em comissão tem finalidade e limites constitucionais próprios." },
{ text: "Em relação à Lei nº 8.112/1990, é correto afirmar que", options: ["rege automaticamente o provimento e a vacância dos servidores estaduais.", "aplica-se a todos os empregados públicos de empresas estatais.", "suas regras são federais e não substituem o estatuto pernambucano.", "revoga o estatuto estadual."], correct: 2, exp: "Para servidores de Pernambuco, a lei estatutária estadual é essencial para conhecer prazos e penalidades." },
{ text: "Assinale a alternativa que NÃO é hipótese de vacância citada no conteúdo.", options: ["Exoneração.", "Demissão.", "Aposentadoria.", "Remoção entre cargos preenchidos, sem desocupação."], correct: 3, exp: "Vacância é a desocupação do cargo, por exoneração, demissão, aposentadoria, falecimento ou outras hipóteses legais." },
{ text: "Uma ação funcional causa dano a visitante de unidade prisional. Segundo a Constituição, a vítima", options: ["deve demandar diretamente o agente, que responde objetivamente.", "não pode ser indenizada.", "só pode agir após condenação penal do agente.", "pode buscar reparação do Estado, que responde objetivamente, com direito de regresso contra o agente nos casos de dolo ou culpa."], correct: 3, exp: "O Estado responde objetivamente perante a vítima; regresso exige dolo ou culpa do agente." },
{ text: "Sobre as esferas de responsabilidade, assinale a correta.", options: ["As instâncias são absolutamente independentes, sem qualquer repercussão entre elas.", "A reparação civil substitui a sanção disciplinar.", "A decisão penal que afirme inexistência do fato ou negativa de autoria repercute na esfera administrativa.", "A absolvição penal por falta de prova impede sempre a apuração administrativa."], correct: 2, exp: "As instâncias são relativamente independentes. A absolvição por falta de prova, em regra, não impede por si só a apuração administrativa." },
{ text: "A responsabilização administrativa do agente exige", options: ["presunção de culpa pelo cargo.", "condenação criminal prévia.", "nexo entre conduta e dever funcional, competência sancionadora, prescrição observada e penalidade prevista no regime.", "apenas dano patrimonial."], correct: 2, exp: "A autoridade não pode presumir culpa pelo cargo nem punir sem procedimento adequado." },
{ text: "A responsabilidade penal do agente público", options: ["depende de crime ou contravenção previsto em lei, segundo tipicidade e culpabilidade.", "decorre automaticamente de qualquer irregularidade administrativa.", "dispensa tipicidade.", "é a mesma que a civil."], correct: 0, exp: "Irregularidade administrativa não gera, por si, responsabilidade penal. A civil exige dano e nexo causal." }
],
"Improbidade administrativa": [
{ text: "Após as alterações da Lei nº 14.230/2021, a improbidade administrativa exige", options: ["conduta culposa ou dolosa, indistintamente.", "apenas a ocorrência de dano.", "somente a posição hierárquica do agente.", "conduta dolosa tipificada, não bastando voluntariedade genérica, ilegalidade ou mera falha administrativa."], correct: 3, exp: "A reforma afastou a improbidade culposa. A responsabilização não é automática pelo resultado nem pela posição hierárquica." },
{ text: "Uma compra mal planejada, sem demonstração de dolo e de enquadramento em tipo legal, configura improbidade administrativa?", options: ["Sim, pois toda ilegalidade é improbidade.", "Sim, pois o dano basta.", "Não, por si só; é preciso demonstrar o enquadramento legal e os elementos exigidos.", "Sim, se o gestor for ocupante de cargo de chefia."], correct: 2, exp: "Mera falha administrativa ou ilegalidade isolada não basta. A mera ocorrência de dano também não substitui os elementos do tipo." },
{ text: "Os atos de improbidade agrupam-se em atos que", options: ["apenas causam lesão ao erário.", "apenas atentam contra a moralidade.", "importam enriquecimento ilícito, causam lesão ao erário ou atentam contra princípios da Administração.", "são todos de natureza penal."], correct: 2, exp: "Cada grupo tem requisitos próprios, e a lei foi alterada pela Lei nº 14.230/2021." },
{ text: "O enriquecimento ilícito, como ato de improbidade, exige", options: ["vantagem patrimonial indevida em razão do exercício da função.", "qualquer ilegalidade formal.", "apenas desobediência a ordem.", "dano ao erário necessariamente."], correct: 0, exp: "O tipo pressupõe vantagem patrimonial indevida. A lesão ao erário exige ação ou omissão dolosa que cause perda patrimonial efetiva." },
{ text: "Quanto aos atos contra princípios da Administração, é correto afirmar que", options: ["qualquer violação ética configura improbidade.", "dispensam dolo.", "dependem de enquadramento nas condutas taxativamente previstas na lei, não de referência abstrata a qualquer violação.", "não admitem defesa."], correct: 2, exp: "A categoria não transforma qualquer ilegalidade em improbidade; confira o tipo legal específico." },
{ text: "Um fornecedor responde por improbidade quando", options: ["apenas contratou com o poder público.", "integra qualquer licitação.", "tem relação de amizade com o gestor.", "induz ou concorre dolosamente para o ato, ou dele se beneficia direta ou indiretamente, conforme as regras legais."], correct: 3, exp: "A participação de particular requer prova de conduta dolosa e vínculo com o ato. A responsabilidade é individualizada." },
{ text: "Sobre as sanções por improbidade, assinale a incorreta.", options: ["Podem incluir perda da função pública e suspensão dos direitos políticos, conforme o caso.", "Podem incluir ressarcimento e multa civil.", "Dependem de processo judicial e garantias de defesa.", "Aplicam-se sempre todas cumulativamente e sem fundamentação."], correct: 3, exp: "As sanções dependem da espécie do ato e da gravidade, e não são necessariamente cumulativas nem escolhidas sem fundamentação." },
{ text: "A indisponibilidade patrimonial decretada no curso do processo de improbidade", options: ["equivale à condenação definitiva.", "dispensa decisão judicial.", "é medida cautelar com requisitos próprios, não punição antecipada.", "substitui o ressarcimento."], correct: 2, exp: "Não se confunde indisponibilidade cautelar com condenação. Ressarcimento recompõe dano e não se confunde com multa." },
{ text: "A apuração de desvio de recurso público pode gerar", options: ["processo de improbidade e processo disciplinar, cada qual com objeto e garantias próprios.", "apenas processo de improbidade, afastando as demais esferas.", "somente processo penal.", "nenhum processo, se houver ressarcimento."], correct: 0, exp: "A Lei de Improbidade não substitui os regimes penal, disciplinar, eleitoral ou de contas; fatos podem repercutir em mais de uma esfera." },
{ text: "Sobre o Tema 1.199 do Supremo Tribunal Federal, é correto afirmar que", options: ["autoriza a retroatividade irrestrita de toda alteração da Lei nº 14.230/2021.", "proíbe qualquer aplicação da reforma.", "trata apenas de improbidade eleitoral.", "definiu parâmetros intertemporais sobre a exigência de dolo e a prescrição, distinguindo processos sem trânsito em julgado de condenações definitivas."], correct: 3, exp: "O tema não autoriza afirmar retroatividade irrestrita. Em prova, deve-se separar texto legal vigente, decisão vinculante e hipótese temporal concreta." }
]
});
})();
